    if (synthStatus === 'success' || implementStatus === 'success' || programStatus === 'success') return 'DONE';
    if (synthStatus === 'canceled' || implementStatus === 'canceled' || programStatus === 'canceled') return 'WARNING';
    return 'NOT READY';
